#!/usr/bin/env node
/**
 * AICodePath Fix Proposal Manager
 *
 * Manages fix proposals generated by code review findings.
 * When a reviewer issues REQUEST_CHANGES, each critical/major finding
 * becomes a fix proposal that can be approved → task or rejected.
 *
 * Auto-escalation: After N consecutive failures on a task, a fix task
 * is automatically created in tasks.md.
 *
 * Proposals are stored as newline-delimited JSON (JSONL) at:
 *   aicodepath-docs/pending-fix-proposals.jsonl
 *
 * @module lib/fix-proposal-manager
 */

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { findProjectRoot } = require('./path-resolver');
const logger = require('./logger');

/** File where proposals are persisted */
const PROPOSALS_FILENAME = 'pending-fix-proposals.jsonl';

/** Valid severity levels */
const SEVERITY_LEVELS = ['critical', 'major', 'minor'];

/** Valid proposal statuses */
const PROPOSAL_STATUSES = ['pending', 'approved', 'rejected', 'escalated'];

/** Auto-escalation threshold: N consecutive failures → create task */
const ESCALATION_THRESHOLD = 3;

/** Failure category classifiers (pattern → category) */
const FAILURE_CATEGORIES = {
  SyntaxError: 'syntax_error',
  ImportError: 'import_error',
  TypeError: 'type_error',
  AssertionError: 'assertion_error',
  ETIMEDOUT: 'timeout',
  ECONNREFUSED: 'timeout',
  ReferenceError: 'runtime_error',
  RangeError: 'runtime_error',
};

/**
 * Get absolute path to proposals file.
 *
 * @param {string} [projectRoot]
 * @returns {string}
 */
function getProposalsPath(projectRoot) {
  const root = projectRoot || findProjectRoot(process.cwd());
  return path.join(root, 'aicodepath-docs', PROPOSALS_FILENAME);
}

/**
 * Generate a short unique proposal ID.
 *
 * @returns {string} e.g. "fp_a3b1c2"
 */
function generateId() {
  return 'fp_' + crypto.randomBytes(3).toString('hex');
}

/**
 * Read all proposals from JSONL file.
 *
 * @param {string} [projectRoot]
 * @returns {Object[]} Array of proposal objects
 */
function readProposals(projectRoot) {
  const filePath = getProposalsPath(projectRoot);
  if (!fs.existsSync(filePath)) return [];

  try {
    const lines = fs.readFileSync(filePath, 'utf-8').split('\n').filter((l) => l.trim());
    return lines.map((line) => JSON.parse(line));
  } catch (err) {
    logger.info('Could not read fix proposals file', { context: 'fix-proposal-manager', error: err.message });
    return [];
  }
}

/**
 * Write all proposals back to JSONL file (full rewrite).
 *
 * @param {Object[]} proposals
 * @param {string} [projectRoot]
 */
function writeProposals(proposals, projectRoot) {
  const filePath = getProposalsPath(projectRoot);
  const dir = path.dirname(filePath);

  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }

  const content = proposals.map((p) => JSON.stringify(p)).join('\n') + (proposals.length > 0 ? '\n' : '');
  fs.writeFileSync(filePath, content, 'utf-8');
}

/**
 * Append a single proposal to JSONL file (append-only, no full rewrite).
 *
 * @param {Object} proposal
 * @param {string} [projectRoot]
 */
function appendProposal(proposal, projectRoot) {
  const filePath = getProposalsPath(projectRoot);
  const dir = path.dirname(filePath);

  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }

  fs.appendFileSync(filePath, JSON.stringify(proposal) + '\n', 'utf-8');
}

/**
 * Classify a failure message into a failure category.
 *
 * @param {string} errorMessage - Error message text
 * @returns {string} Category key from FAILURE_CATEGORIES or 'unknown'
 */
function classifyFailure(errorMessage) {
  for (const [pattern, category] of Object.entries(FAILURE_CATEGORIES)) {
    if (errorMessage.includes(pattern)) return category;
  }
  return 'unknown';
}

/**
 * Create a fix proposal from a review finding.
 *
 * @param {Object} finding
 * @param {string} finding.severity   - 'critical' | 'major' | 'minor'
 * @param {string} finding.location   - 'file:line' format
 * @param {string} finding.issue      - Description of the problem
 * @param {string} [finding.suggestion] - How to fix it
 * @param {boolean} [finding.autoFixable] - Whether Lead can auto-apply
 * @param {string} originalTaskId     - Task ID that generated this finding
 * @param {string} [projectRoot]
 * @returns {Object} The created proposal
 */
function createProposal(finding, originalTaskId, projectRoot) {
  if (!finding || !finding.issue) {
    throw new Error('finding.issue is required');
  }
  if (!originalTaskId) {
    throw new Error('originalTaskId is required');
  }
  const severity = SEVERITY_LEVELS.includes(finding.severity) ? finding.severity : 'minor';

  const proposal = {
    id: generateId(),
    originalTaskId,
    severity,
    location: finding.location || 'unknown',
    issue: finding.issue,
    suggestion: finding.suggestion || '',
    autoFixable: Boolean(finding.autoFixable),
    status: 'pending',
    createdAt: new Date().toISOString(),
    resolvedAt: null,
    failureCategory: null,
    consecutiveFailures: 0,
  };

  appendProposal(proposal, projectRoot);

  logger.info('Fix proposal created', {
    context: 'fix-proposal-manager',
    proposalId: proposal.id,
    severity: proposal.severity,
    originalTaskId,
    location: proposal.location,
  });

  return proposal;
}

/**
 * List proposals filtered by status and/or task ID.
 *
 * @param {Object} [filter]
 * @param {string} [filter.status]        - Filter by status
 * @param {string} [filter.taskId]        - Filter by original task ID
 * @param {string} [filter.severity]      - Filter by severity
 * @param {string} [projectRoot]
 * @returns {Object[]} Matching proposals
 */
function listProposals(filter = {}, projectRoot) {
  const proposals = readProposals(projectRoot);
  return proposals.filter((p) => {
    if (filter.status && p.status !== filter.status) return false;
    if (filter.taskId && p.originalTaskId !== filter.taskId) return false;
    if (filter.severity && p.severity !== filter.severity) return false;
    return true;
  });
}

/**
 * Update a proposal's status.
 *
 * @param {string} proposalId
 * @param {string} newStatus - One of PROPOSAL_STATUSES
 * @param {string} [projectRoot]
 * @returns {Object|null} Updated proposal or null if not found
 */
function updateStatus(proposalId, newStatus, projectRoot) {
  if (!PROPOSAL_STATUSES.includes(newStatus)) {
    throw new Error(`Invalid status: ${newStatus}. Must be one of: ${PROPOSAL_STATUSES.join(', ')}`);
  }

  const proposals = readProposals(projectRoot);
  const idx = proposals.findIndex((p) => p.id === proposalId);
  if (idx === -1) return null;

  proposals[idx].status = newStatus;
  if (['approved', 'rejected', 'escalated'].includes(newStatus)) {
    proposals[idx].resolvedAt = new Date().toISOString();
  }

  writeProposals(proposals, projectRoot);

  logger.info('Fix proposal status updated', {
    context: 'fix-proposal-manager',
    proposalId,
    newStatus,
  });

  return proposals[idx];
}

/**
 * Record a task failure and check if escalation threshold is reached.
 * Auto-escalates by creating a task entry in tasks.md when N consecutive failures occur.
 *
 * @param {string} taskId          - The failing task ID
 * @param {string} errorMessage    - Error message from the failure
 * @param {string} [tasksFilePath] - Path to tasks.md
 * @param {string} [projectRoot]
 * @returns {{ escalated: boolean, consecutiveFailures: number, proposal: Object|null }}
 */
function recordFailure(taskId, errorMessage, tasksFilePath, projectRoot) {
  const root = projectRoot || findProjectRoot(process.cwd());
  const tasksPath = tasksFilePath || path.join(root, 'aicodepath-docs', 'tasks.md');

  const proposals = readProposals(root);

  // Find or create a tracking entry for this task's consecutive failures
  let trackingEntry = proposals.find(
    (p) => p.originalTaskId === taskId && p.status === 'pending' && p.failureCategory === classifyFailure(errorMessage)
  );

  if (!trackingEntry) {
    trackingEntry = createProposal(
      {
        severity: 'major',
        location: `task:${taskId}`,
        issue: `Consecutive failure: ${errorMessage.substring(0, 200)}`,
        suggestion: 'Investigate root cause and apply fix',
        autoFixable: false,
      },
      taskId,
      root
    );
    trackingEntry.failureCategory = classifyFailure(errorMessage);
    trackingEntry.consecutiveFailures = 0;
  }

  trackingEntry.consecutiveFailures = (trackingEntry.consecutiveFailures || 0) + 1;

  const shouldEscalate = trackingEntry.consecutiveFailures >= ESCALATION_THRESHOLD;

  if (shouldEscalate && trackingEntry.status === 'pending') {
    trackingEntry.status = 'escalated';
    trackingEntry.resolvedAt = new Date().toISOString();

    // Append BLOCKED marker to tasks.md
    if (fs.existsSync(tasksPath)) {
      const escalationNote = `\n> **BLOCKED** Task ${taskId} escalated after ${ESCALATION_THRESHOLD} consecutive failures (${trackingEntry.failureCategory}) — fix proposal ${trackingEntry.id} created.\n`;
      fs.appendFileSync(tasksPath, escalationNote, 'utf-8');
    }

    logger.info('Task escalated after consecutive failures', {
      context: 'fix-proposal-manager',
      taskId,
      proposalId: trackingEntry.id,
      consecutiveFailures: trackingEntry.consecutiveFailures,
      category: trackingEntry.failureCategory,
    });
  }

  // Update in proposals array
  const allProposals = readProposals(root);
  const idx = allProposals.findIndex((p) => p.id === trackingEntry.id);
  if (idx !== -1) {
    allProposals[idx] = trackingEntry;
    writeProposals(allProposals, root);
  }

  return {
    escalated: shouldEscalate,
    consecutiveFailures: trackingEntry.consecutiveFailures,
    proposal: trackingEntry,
  };
}

module.exports = {
  createProposal,
  listProposals,
  updateStatus,
  recordFailure,
  classifyFailure,
  readProposals,
  getProposalsPath,
  SEVERITY_LEVELS,
  PROPOSAL_STATUSES,
  ESCALATION_THRESHOLD,
  FAILURE_CATEGORIES,
};
